-- Módulo 46: seguimiento manual y constancia textual de recepción.
CREATE TABLE "EntregasDespacho" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Codigo" varchar(20) NOT NULL CHECK ("Codigo" = btrim("Codigo") AND length("Codigo") > 0),
    "ReferenciaGuia" varchar(40) NOT NULL CHECK ("ReferenciaGuia" = btrim("ReferenciaGuia") AND length("ReferenciaGuia") > 0),
    "Destinatario" varchar(200) NOT NULL CHECK ("Destinatario" = btrim("Destinatario") AND length("Destinatario") > 0),
    "DireccionDestino" varchar(300) NOT NULL CHECK ("DireccionDestino" = btrim("DireccionDestino") AND length("DireccionDestino") > 0),
    "FechaProgramada" timestamptz NOT NULL,
    "Observaciones" varchar(500),
    "Estado" varchar(15) NOT NULL DEFAULT 'Programada',
    "FechaSalida" timestamptz,
    "FechaEntrega" timestamptz,
    "FechaCancelacion" timestamptz,
    "Receptor" varchar(100),
    "DocumentoReceptor" varchar(20),
    "ReferenciaConstancia" varchar(100),
    "ObservacionesEntrega" varchar(500),
    "MotivoCancelacion" varchar(500),
    CONSTRAINT "CK_EntregasDespacho_Estado" CHECK (
        ("Estado" = 'Programada' AND "FechaSalida" IS NULL AND "FechaEntrega" IS NULL AND "FechaCancelacion" IS NULL) OR
        ("Estado" = 'EnRuta' AND "FechaSalida" IS NOT NULL AND "FechaEntrega" IS NULL AND "FechaCancelacion" IS NULL) OR
        ("Estado" = 'Entregada' AND "FechaSalida" IS NOT NULL AND "FechaEntrega" IS NOT NULL AND "FechaCancelacion" IS NULL) OR
        ("Estado" = 'Cancelada' AND "FechaEntrega" IS NULL AND "FechaCancelacion" IS NOT NULL)),
    CONSTRAINT "CK_EntregasDespacho_Pod" CHECK (
        ("Estado" = 'Entregada' AND "Receptor" IS NOT NULL AND length(btrim("Receptor")) > 0
            AND "DocumentoReceptor" IS NOT NULL AND length(btrim("DocumentoReceptor")) > 0
            AND "ReferenciaConstancia" IS NOT NULL AND length(btrim("ReferenciaConstancia")) > 0) OR
        ("Estado" <> 'Entregada' AND "Receptor" IS NULL AND "DocumentoReceptor" IS NULL AND "ReferenciaConstancia" IS NULL AND "ObservacionesEntrega" IS NULL)),
    CONSTRAINT "CK_EntregasDespacho_Cancelacion" CHECK (
        ("Estado" = 'Cancelada' AND "MotivoCancelacion" IS NOT NULL AND length(btrim("MotivoCancelacion")) > 0) OR
        ("Estado" <> 'Cancelada' AND "MotivoCancelacion" IS NULL))
);
CREATE UNIQUE INDEX "IX_EntregasDespacho_Codigo" ON "EntregasDespacho" (lower(btrim("Codigo")));
CREATE TABLE "EventosEntrega" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EntregaDespachoId" integer NOT NULL REFERENCES "EntregasDespacho" ("Id") ON DELETE CASCADE,
    "Estado" varchar(15) NOT NULL CHECK ("Estado" IN ('Programada','EnRuta','Entregada','Cancelada')),
    "Fecha" timestamptz NOT NULL,
    "Descripcion" varchar(500) NOT NULL CHECK (length(btrim("Descripcion")) > 0)
);
CREATE INDEX "IX_EventosEntrega_EntregaDespachoId" ON "EventosEntrega" ("EntregaDespachoId");
